style.css:
@-moz-document domain("adventofcode.com") {
/* i really want this to be global */
      body {
          background: #0f0f15;
          font-family: Arial, Helvetica, sans-serif;
      }
      article em {
          color: #ff0000;
          font-style: normal;
          text-shadow: none;
      }
      code {
          background-color: #000000;
          color: #00ffff;
      }
      .day-success {
          color: #d4af37;
          text-shadow: 0 0 5px #d4af37;
      }
      article em.star {
          color: #d4af37;
          text-shadow: 0 0 5px #d4af37;
}
}
